import plotly.graph_objects as go

fig = go.Figure(
    data=[go.Scatter(x=[1, 2, 3], y=[4, 5, 6], mode="markers")],
    frames=[
        go.Frame(data=[go.Scatter(x=[1, 2, 3], y=[4, 5, 6])], name="1"),
        go.Frame(data=[go.Scatter(x=[1, 2, 3], y=[4, 5, 6])], name="2"),
    ],
    layout=go.Layout(
        sliders=[{
            "steps": [
                {"args": [["1"], {"frame": {"duration": 0}, "mode": "immediate"}], "label": "1", "method": "animate"},
                {"args": [["2"], {"frame": {"duration": 0}, "mode": "immediate"}], "label": "2", "method": "animate"},
            ]
        }]
    )
)
fig.show()

import plotly.graph_objects as go

fig = go.Figure(
    data=[go.Scatter(x=[1, 2, 3], y=[4, 5, 6], mode="markers")],
    frames=[go.Frame(data=[go.Scatter(x=[1, 2, 3], y=[4, 5, 6])], name="f1")],
    layout=go.Layout(
        updatemenus=[{
            "buttons": [
                {"label": "Play", "method": "animate", "args": [None]},
                {"label": "Pause", "method": "animate", "args": [[None], {"frame": {"duration": 0}, "mode": "immediate"}]},
            ]
        }]
    )
)
fig.show()
